figures.asymptoteSource:
// The two sides that enclose angle C, and the side c that closes the
// triangle. Dropping a perpendicular from one endpoint of a to the line of b
// splits side c into a horizontal piece b cos C and a vertical piece a sin C,
// which is exactly where the cosine term in the law of cosines comes from.
size(340,240);
pair O = (0,0);
pair P = (4.5,0);
pair Q = (4.5*0.5, 4.5*0.866);
pair F = (4.5*0.5, 0);
draw(O--P--Q--cycle, black);
draw(Q--F, dashed);
draw(O--F, dotted);
label("$O$", O, SW);
label("$P$", P, SE);
label("$Q$", Q, N);
label("$F$", F, S);
label("$b$", (O+P)/2, S);
label("$a$", (P+Q)/2, E);
label("$c$", (O+Q)/2, NW);
label("$b\\cos C$", (O+F)/2, S);
label("$a\\sin C$", (F+Q)/2, E);
label("$C$", (0.4,0.1), NE);

// The law of sines as a single circle. Inscribing a triangle in a circle of
// radius R makes every side a chord, and the chord subtending angle A has
// length 2R sin A, so one ratio a over sin A accounts for all three sides.
size(320,300);
pair O = (0,0);
pair A = dir(110);
pair B = dir(200);
pair C = dir(345);
draw(scale(1.15)*unitcircle, gray(0.7));
draw(A--B--C--cycle, black);
draw(O--A, gray(0.5));
draw(O--B, gray(0.5));
draw(O--C, gray(0.5));
label("$O$", O, SW);
label("$A$", A, NW);
label("$B$", B, S);
label("$C$", C, E);
label("$a$", (B+C)/2 + (0.16,0.1), SE);
label("$b$", (C+A)/2 + (0.2,0), E);
label("$c$", (A+B)/2 + (-0.2,0), W);
label("$R$", O*1.35, SW);
label("$\\frac{a}{\\sin A} = \\frac{b}{\\sin B} = \\frac{c}{\\sin C} = 2R$", (0,-1.42), S);

// The two triangles a diagonal cuts from a cyclic quadrilateral, showing
// that opposite angles are supplementary and so the areas share the sine of
// the same angle.
size(340,240);
pair O = (0,0);
pair A = dir(120);
pair B = dir(40);
pair C = dir(-30);
pair D = dir(210);
draw(scale(1.1)*unitcircle, gray(0.7));
draw(A--B--C--D--cycle, black);
draw(A--C, dashed);
label("$A$", A, NW);
label("$B$", B, NE);
label("$C$", C, E);
label("$D$", D, SW);
label("$AC$", (A+C)/2, SE);
label("$\\frac{1}{2}bd\\sin A$", (A+B+C)/3 - (0.15,0.1), NE);
label("$\\frac{1}{2}bd\\sin D$", (A+C+D)/3 - (0.15,-0.1), SW);
label("$d$", (B+C)/2 + (0.18,0), E);
label("$\\sin D = \\sin A$", (0,-1.28), S);

